// Lọc các bản ghi chưa có trong currentData
let addedCount = 0;
for (const nh of newHospitals) {
  const existingIdx = currentData.findIndex(h => h.slug === nh.slug || h.id === nh.id);
  if (existingIdx >= 0) {
    // Cập nhật lại bản ghi nếu đã có
    currentData[existingIdx] = nh;
    console.log(`Updated existing hospital: ${nh.name}`);
  } else {
    currentData.push(nh);
    addedCount++;
    console.log(`Added new hospital: ${nh.name}`);
  }
}

fs.writeFileSync(filePath, JSON.stringify(currentData, null, 2), 'utf8');
console.log(`\nDONE: Successfully added ${addedCount} new hospitals.`);
console.log(`Total hospitals in database: ${currentData.length}`);
